/**
 * Machine-readable version of the file-ownership matrix in AGENTS.md §3.
 *
 * OWNER: PM. Agents do not edit this file — it is what checks them.
 *
 * Keep in sync with AGENTS.md §3. If the two disagree, this file wins,
 * because it is the one that actually runs.
 *
 * Patterns: `**` matches any depth, `*` matches within one segment.
 * A path with no `*` must match exactly.
 */

/**
 * Shared ground.
 *
 * Task status and blockers: every agent updates its own row.
 *
 * Unit tests and their fixtures: whoever writes the code writes its tests.
 * QA-BOT owns end-to-end tests, not the unit layer — the matrix used to give
 * it all of tests/**, which flagged DEV-INT for adding tests to the Drive
 * client it had just written.
 */
export const COMMON = [
  "tasks/TASK-INDEX.md",
  "tasks/BLOCKERS.md",
  // Every agent needs to add a dependency sooner or later, and only DEV-OPS
  // owned the file that lists them. The part worth guarding is the scripts
  // block — the gates live there — and verify-ownership.mjs guards that
  // separately, for everyone but DEV-OPS and PM.
  "package.json",
  "package-lock.json",
  "tests/unit/**",
  "tests/fixtures/**",
];

/**
 * Only the PM writes these. They are the rules and the gates; an agent that
 * can edit its own examiner is not being examined.
 */
export const PROTECTED = [
  "AGENTS.md",
  "GEMINI.md",
  "scripts/ownership.mjs",
  "scripts/verify-ownership.mjs",
  "scripts/verify-db.mjs",
  "scripts/verify-build.mjs",
  "scripts/verify-prod.mjs",
  "scripts/verify-wired.mjs",
];

