/** Turns a glob into a regex anchored at both ends. */
function toRegExp(pattern) {
  let out = "";
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === "*") {
      if (pattern[i + 1] === "*") {
        if (pattern[i + 2] === "/") {
          // `a/**/b` matches `a/b` too, so the whole segment is optional.
          out += "(?:.*/)?";
          i += 2;
        } else {
          out += ".*";
          i += 1;
        }
      } else {
        out += "[^/]*";
      }
    } else if (".+^${}()|[]\\".includes(c)) {
      // Route groups like (admin) put regex metacharacters in real paths.
      out += "\\" + c;
    } else {
      out += c;
    }
  }
  return new RegExp(`^${out}$`);
}

export function matches(pattern, file) {
  return toRegExp(pattern).test(file);
}

/** Every agent allowed to write `file`, ignoring COMMON and PROTECTED. */
export function ownersOf(file) {
  return Object.entries(OWNERSHIP)
    .filter(([name, patterns]) => name !== "PM" && patterns.some((p) => matches(p, file)))
    .map(([name]) => name);
}

export function isCommon(file) {
  return COMMON.some((p) => matches(p, file));
}

export function isProtected(file) {
  return PROTECTED.some((p) => matches(p, file));
}

export const AGENT_NAMES = Object.keys(OWNERSHIP);
